  1006  // Name decoder
  1007
  1008  static int decode_name(name_context *ctx, char *name, int name_len) {
  1009      int t0 = decode_token_type(ctx, 0);
  1010      uint32_t dist;
  1011      int pnum, cnum = ctx->counter++;
  1012
  1013      if (cnum >= ctx->max_names)
  1014          return -1;
  1015
  1016      if (t0 < 0 || t0 >= ctx->max_tok*16)
  1017          return 0;
  1018
  1019      if (decode_token_int(ctx, 0, t0, &dist) < 0 || dist > cnum)
  1020          return -1;
  1021      if ((pnum = cnum - dist) < 0) pnum = 0;
  1022
  1023      //fprintf(stderr, "t0=%d, dist=%d, pnum=%d, cnum=%d\n", t0, dist, pnum, cnum);
  1024
  1025      if (t0 == N_DUP) {
  1026          if (pnum == cnum)
  1027              return -1;
  1028
  1029          if (strlen(ctx->lc[pnum].last_name) +1 >= name_len) return -1;
  1030          strcpy(name, ctx->lc[pnum].last_name);
  1031          // FIXME: optimise this
  1032          ctx->lc[cnum].last_name = name;
  1033          ctx->lc[cnum].last_ntok = ctx->lc[pnum].last_ntok;
  1034          int nc = ctx->lc[cnum].last_ntok ? ctx->lc[cnum].last_ntok : MAX_TOKENS;
  1035          memcpy(ctx->lc[cnum].last_token_type, ctx->lc[pnum].last_token_type, nc * sizeof(int));
  1036          memcpy(ctx->lc[cnum].last_token_int , ctx->lc[pnum].last_token_int , nc * sizeof(int));
  1037          memcpy(ctx->lc[cnum].last_token_str , ctx->lc[pnum].last_token_str , nc * sizeof(int));
  1038
  1039          return strlen(name)+1;
  1040      }
  1041
  1042      *name = 0;
  1043      int ntok, len = 0, len2;
  1044
  1045      for (ntok = 1; ntok < MAX_TOKENS && ntok < ctx->max_tok; ntok++) {
  1046          uint32_t v, vl;
  1047          enum name_type tok;
  1048          tok = decode_token_type(ctx, ntok);
  1049          //fprintf(stderr, "Tok %d = %d\n", ntok, tok);
  1050
  1051          switch (tok) {
  1052          case N_CHAR:
  1053              if (len+1 >= name_len) return -1;
  1054              if (decode_token_char(ctx, ntok, &name[len]) < 0) return -1;
  1055              //fprintf(stderr, "Tok %d CHAR %c\n", ntok, name[len]);
  1056              ctx->lc[cnum].last_token_type[ntok] = N_CHAR;
  1057              ctx->lc[cnum].last_token_int [ntok] = name[len++];
  1058              break;
  1059
  1060          case N_ALPHA:
  1061              if ((len2 = decode_token_alpha(ctx, ntok, &name[len], name_len - len)) < 0)
  1062                  return -1;
  1063              //fprintf(stderr, "Tok %d ALPHA %.*s\n", ntok, len2, &name[len]);
  1064              ctx->lc[cnum].last_token_type[ntok] = N_ALPHA;
  1065              ctx->lc[cnum].last_token_str [ntok] = len;
  1066              ctx->lc[cnum].last_token_int [ntok] = len2;
  1067              len += len2;
  1068              break;
  1069
  1070          case N_DIGITS0: // [0-9]*
  1071              if (decode_token_int1(ctx, ntok, N_DZLEN, &vl) < 0) return -1;
  1072              if (decode_token_int(ctx, ntok, N_DIGITS0, &v) < 0) return -1;
  1073              if (len+20+vl >= name_len) return -1;
  1074              len += append_uint32_fixed(&name[len], v, vl);
  1075              //fprintf(stderr, "Tok %d DIGITS0 %0*d\n", ntok, vl, v);
  1076              ctx->lc[cnum].last_token_type[ntok] = N_DIGITS0;
  1077              ctx->lc[cnum].last_token_int [ntok] = v;
  1078              ctx->lc[cnum].last_token_str [ntok] = vl;
  1079              break;
  1080
  1081          case N_DDELTA0:
  1082              if (decode_token_int1(ctx, ntok, N_DDELTA0, &v) < 0) return -1;
  1083              v += ctx->lc[pnum].last_token_int[ntok];
  1084              if (len+ctx->lc[pnum].last_token_str[ntok]+1 >= name_len) return -1;
  1085              len += append_uint32_fixed(&name[len], v, ctx->lc[pnum].last_token_str[ntok]);
  1086              //fprintf(stderr, "Tok %d DELTA0 %0*d\n", ntok, ctx->lc[pnum].last_token_str[ntok], v);
  1087              ctx->lc[cnum].last_token_type[ntok] = N_DIGITS0;
  1088              ctx->lc[cnum].last_token_int [ntok] = v;
  1089              ctx->lc[cnum].last_token_str [ntok] = ctx->lc[pnum].last_token_str[ntok];
  1090              break;
  1091
  1092          case N_DIGITS: // [1-9][0-9]*
  1093              if (decode_token_int(ctx, ntok, N_DIGITS, &v) < 0) return -1;
  1094              if (len+20 >= name_len) return -1;
  1095              len += append_uint32_var(&name[len], v);
  1096              //fprintf(stderr, "Tok %d DIGITS %d\n", ntok, v);
  1097              ctx->lc[cnum].last_token_type[ntok] = N_DIGITS;
  1098              ctx->lc[cnum].last_token_int [ntok] = v;
  1099              break;
  1100
  1101          case N_DDELTA:
  1102              if (decode_token_int1(ctx, ntok, N_DDELTA, &v) < 0) return -1;
  1103              v += ctx->lc[pnum].last_token_int[ntok];
  1104              if (len+20 >= name_len) return -1;
  1105              len += append_uint32_var(&name[len], v);
  1106              //fprintf(stderr, "Tok %d DELTA %d\n", ntok, v);
  1107              ctx->lc[cnum].last_token_type[ntok] = N_DIGITS;
  1108              ctx->lc[cnum].last_token_int [ntok] = v;
  1109              break;
  1110
  1111          case N_NOP:
  1112              ctx->lc[cnum].last_token_type[ntok] = N_NOP;
  1113              break;
  1114
  1115          case N_MATCH:
  1116              switch (ctx->lc[pnum].last_token_type[ntok]) {
  1117              case N_CHAR:
  1118                  if (len+1 >= name_len) return -1;
  1119                  name[len++] = ctx->lc[pnum].last_token_int[ntok];
  1120                  //fprintf(stderr, "Tok %d MATCH CHAR %c\n", ntok, ctx->lc[pnum].last_token_int[ntok]);
  1121                  ctx->lc[cnum].last_token_type[ntok] = N_CHAR;
  1122                  ctx->lc[cnum].last_token_int [ntok] = ctx->lc[pnum].last_token_int[ntok];
  1123                  break;
  1124
  1125              case N_ALPHA:
  1126                  if (ctx->lc[pnum].last_token_int[ntok] < 0 ||
  1127                      len+ctx->lc[pnum].last_token_int[ntok] >= name_len) return -1;
  1128                  memcpy(&name[len],
  1129                         &ctx->lc[pnum].last_name[ctx->lc[pnum].last_token_str[ntok]],
  1130                         ctx->lc[pnum].last_token_int[ntok]);
  1131                  //fprintf(stderr, "Tok %d MATCH ALPHA %.*s\n", ntok, ctx->lc[pnum].last_token_int[ntok], &name[len]);
  1132                  ctx->lc[cnum].last_token_type[ntok] = N_ALPHA;
  1133                  ctx->lc[cnum].last_token_str [ntok] = len;
  1134                  ctx->lc[cnum].last_token_int [ntok] = ctx->lc[pnum].last_token_int[ntok];
  1135                  len += ctx->lc[pnum].last_token_int[ntok];
  1135                  len += ctx->lc[pnum].last_token_int[ntok];
  1136                  break;
  1137
  1138              case N_DIGITS:
  1139                  if (len+20 >= name_len) return -1;
  1140                  len += append_uint32_var(&name[len], ctx->lc[pnum].last_token_int[ntok]);
  1141                  //fprintf(stderr, "Tok %d MATCH DIGITS %d\n", ntok, ctx->lc[pnum].last_token_int[ntok]);
  1142                  ctx->lc[cnum].last_token_type[ntok] = N_DIGITS;
  1143                  ctx->lc[cnum].last_token_int [ntok] = ctx->lc[pnum].last_token_int[ntok];
  1144                  break;
  1145
  1146              case N_DIGITS0:
  1147                  if (len+ctx->lc[pnum].last_token_str[ntok] >= name_len) return -1;
  1148                  len += append_uint32_fixed(&name[len], ctx->lc[pnum].last_token_int[ntok], ctx->lc[pnum].last_token_str[ntok]);
  1149                  //fprintf(stderr, "Tok %d MATCH DIGITS %0*d\n", ntok, ctx->lc[pnum].last_token_str[ntok], ctx->lc[pnum].last_token_int[ntok]);
  1150                  ctx->lc[cnum].last_token_type[ntok] = N_DIGITS0;
  1151                  ctx->lc[cnum].last_token_int [ntok] = ctx->lc[pnum].last_token_int[ntok];
  1152                  ctx->lc[cnum].last_token_str [ntok] = ctx->lc[pnum].last_token_str[ntok];
  1153                  break;
  1154
  1155              default:
  1156                  return -1;
  1157              }
  1158              break;
  1159
  1160          default: // an elided N_END
  1161          case N_END:
  1162              if (len+1 >= name_len) return -1;
  1163              name[len++] = 0;
  1164              ctx->lc[cnum].last_token_type[ntok] = N_END;
  1165
  1166              ctx->lc[cnum].last_name = name;
  1167              ctx->lc[cnum].last_ntok = ntok;
  1168
  1169              return len;
  1170          }
  1171      }
  1172
  1173
  1174      return -1;
  1175  }
